CASES=[
('בג"ץ 910/86 רסלר נ\' שר הביטחון','עובדות: חיילי מילואים עתרו נגד הפטור משירות לבחורי ישיבות.','הלכה: הפטור מגדיל את הנטל על העותרים, ולכן הם נפגעים במשתמע; הורחבה זכות העמידה והוכר העותר הציבורי, והוצגה ההבחנה בין שפיטות נורמטיבית למוסדית. העתירה נדחתה לגופה. חשיבות למבחן: הרחבת שערי בג"ץ.'),
('קורן נ\' שר הביטחון; אמסלם נ\' שר הביטחון (2021)','עובדות: עותר בלי זיקה ביקש פינוי יישוב; חבר כנסת ביקש לחייב את השר לחתום על מינוי כשהמועמד עצמו כבר פנה.','הלכה: כשיש נפגע ישיר שלא פנה או לא הצטרף, הנטייה לדחות את עתירת העותר הציבורי: "רב על ריב לא לו". חשיבות למבחן: הסייג לעותר הציבורי.'),
('בג"ץ 8684/20 לשכת עורכי הדין נ\' שר המשפטים','עובדות: עתירה נגד תקנות סדר הדין האזרחי הוגשה שבועיים וחצי לפני כניסתן לתוקף ושלוש שנים אחרי פרסומן.','הלכה: סובייקטיבי – אין צידוק (הלשכה אף השתתפה בגיבוש); אובייקטיבי – נזק כבד לציבור; שלטון החוק – אין פגם מהותי. העתירה נדחתה על הסף. חשיבות למבחן: שלושת יסודות השיהוי.'),
('בג"ץ 2311/11 סבח נ\' הכנסת; בג"ץ חסון נ\' הכנסת (חוק יסוד: הלאום)','עובדות: עתירות נגד ועדות קבלה ביישובים קהילתיים ונגד חוק יסוד: הלאום הוגשו לפני יישום.','הלכה: בסבח הרוב קבע שהעתירה מוקדמת ושאין אינטרס לדון, ונדחתה על הסף. בחסון נקבע שאף אם מוקדמת, יש אינטרס ממשי לדון בשאלה העקרונית, והיא נדונה. חשיבות למבחן: שני שלבי מבחן הבשלות.'),
('כספי (2021–2022); התנועה לאיכות השלטון נ\' מבקר המדינה (2024)','עובדות: עתירות נפרדות הוגשו באותו עניין בעוד עתירה קודמת תלויה ועומדת.','הלכה: בכספי נקבע שיש להצטרף לעתירה הקיימת, אחרת תידחה על הסף. ב-2024 נקבע שהגיעה העת להשתחרר מהלכת כספי כהלכה מחייבת, ולשופט שיקול דעת לכלים אחרים כמו איחוד או הזמנה להצטרף. חשיבות למבחן: עילת סף חדשה וריכוכה.'),
('חוק בתי משפט לעניינים מנהליים, התש"ס–2000 (הוראת חוק)','הקמת ערכאה מנהלית בבתי המשפט המחוזיים להקלת העומס על בג"ץ.','תוכן: ס\' 5 – עתירה (תוספת ראשונה), ערעור (תוספת שנייה), תובענה (תוספת שלישית); ערעור לעליון בזכות בעתירה ובתובענה וברשות בערעור; ס\' 6 – העברה לבג"ץ (חשיבות, רגישות, דחיפות); ס\' 9 – צו ביניים. חשיבות למבחן: שאלת הפורום.'),
('סעיפים 15(ג) ו-15(ד) לחוק יסוד: השפיטה (הוראת חוק)','מקורות סמכות בג"ץ.','תוכן: 15(ג) – סעד למען הצדק בעניין שאינו בסמכות ערכאה אחרת; 15(ד) – ביאס קורפוס, מנדמוס לרשויות וגופים הממלאים תפקיד ציבורי, פיקוח על בתי משפט ובתי דין ייחודיים, ובתי דין דתיים בחריגה מסמכות. חשיבות למבחן: סמכות בג"ץ.'),
]
